-- LytHouse persisted Intelligence + QA + API foundation
create table if not exists public.analysis_runs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, validation_id uuid references public.validations(id) on delete set null, mode text not null default 'smart', depth text not null default 'standard', domains text[] not null default '{}', status text not null default 'queued', config jsonb not null default '{}'::jsonb, created_by uuid references auth.users(id), created_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists public.application_components (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, analysis_run_id uuid references public.analysis_runs(id) on delete cascade, component_type text not null, name text not null, version text, file_path text, metadata jsonb not null default '{}'::jsonb, confidence numeric, created_at timestamptz not null default now());
create table if not exists public.intelligence_evidence (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, analysis_run_id uuid references public.analysis_runs(id) on delete cascade, finding_id uuid references public.findings(id) on delete cascade, evidence_type text not null, source text not null, source_url text, file_path text, line integer, content jsonb not null default '{}'::jsonb, confidence numeric, created_at timestamptz not null default now());
create table if not exists public.api_endpoints (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, analysis_run_id uuid references public.analysis_runs(id) on delete cascade, method text, route text not null, file_path text, line integer, auth_required boolean, metadata jsonb not null default '{}'::jsonb, confidence numeric, created_at timestamptz not null default now());
create table if not exists public.qa_test_cases (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, name text not null, framework text, test_type text, source text not null default 'repository', script text, file_path text, status text not null default 'draft', metadata jsonb not null default '{}'::jsonb, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.qa_test_runs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, test_case_id uuid references public.qa_test_cases(id) on delete set null, analysis_run_id uuid references public.analysis_runs(id) on delete set null, status text not null default 'queued', assertions_passed integer not null default 0, assertions_failed integer not null default 0, stdout text, stderr text, result jsonb not null default '{}'::jsonb, started_at timestamptz, completed_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.qa_gaps (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, analysis_run_id uuid references public.analysis_runs(id) on delete cascade, api_endpoint_id uuid references public.api_endpoints(id) on delete set null, title text not null, category text not null, severity text not null default 'medium', description text, recommended_test text, evidence jsonb not null default '{}'::jsonb, confidence numeric, status text not null default 'open', created_at timestamptz not null default now());
create table if not exists public.external_intelligence (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, analysis_run_id uuid references public.analysis_runs(id) on delete cascade, subject text not null, intelligence_type text not null, vendor text, current_version text, advisory text, source_url text, effective_date date, metadata jsonb not null default '{}'::jsonb, confidence numeric, created_at timestamptz not null default now());
create table if not exists public.jira_issue_links (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, finding_id uuid references public.findings(id) on delete set null, qa_gap_id uuid references public.qa_gaps(id) on delete set null, jira_issue_key text not null, jira_issue_url text, status text, metadata jsonb not null default '{}'::jsonb, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists analysis_runs_project_idx on public.analysis_runs(project_id,created_at desc); create index if not exists components_project_idx on public.application_components(project_id,component_type); create index if not exists evidence_project_idx on public.intelligence_evidence(project_id,evidence_type); create index if not exists api_endpoints_project_idx on public.api_endpoints(project_id); create index if not exists qa_cases_project_idx on public.qa_test_cases(project_id); create index if not exists qa_runs_project_idx on public.qa_test_runs(project_id,created_at desc); create index if not exists qa_gaps_project_idx on public.qa_gaps(project_id,status); create index if not exists external_intel_project_idx on public.external_intelligence(project_id,created_at desc); create index if not exists jira_links_project_idx on public.jira_issue_links(project_id);
alter table public.analysis_runs enable row level security; alter table public.application_components enable row level security; alter table public.intelligence_evidence enable row level security; alter table public.api_endpoints enable row level security; alter table public.qa_test_cases enable row level security; alter table public.qa_test_runs enable row level security; alter table public.qa_gaps enable row level security; alter table public.external_intelligence enable row level security; alter table public.jira_issue_links enable row level security;
do $$ declare t text; begin foreach t in array array['analysis_runs','application_components','intelligence_evidence','api_endpoints','qa_test_cases','qa_test_runs','qa_gaps','external_intelligence','jira_issue_links'] loop execute format('drop policy if exists workspace_member_access on public.%I',t); execute format('create policy workspace_member_access on public.%I for all to authenticated using (exists (select 1 from public.workspace_members wm where wm.workspace_id=%I.workspace_id and wm.user_id=auth.uid())) with check (exists (select 1 from public.workspace_members wm where wm.workspace_id=%I.workspace_id and wm.user_id=auth.uid()))',t,t,t); end loop; end $$;